theorem integral_exp_mul_I_scaled (a T : ℝ) :
    ∫ t in (-T)..T, Complex.exp (((t * a : ℝ) : ℂ) * I) =
      if a = 0 then (2 * T : ℂ) else (2 * Real.sin (T * a) : ℂ) / (a : ℂ)

theorem intervalIntegral_sin_div_kernel_scalar_mass_eq_scaled (T R : ℝ) :
    (∫ u in (-R)..R,
      if u = 0 then (0 : ℂ) else (Real.sin (T * u) / (π * u) : ℂ)) =
      (1 / (π : ℂ)) *
        ∫ v in (T * (-R))..(T * R),
          if v = 0 then (0 : ℂ) else (Real.sin v / v : ℂ)

theorem intervalIntegral_sin_div_kernel_neg_zero_eq_zero_to (A : ℝ) :
    (∫ v in (-A)..0,
      if v = 0 then (0 : ℂ) else (Real.sin v / v : ℂ)) =
      ∫ v in 0..A,
        if v = 0 then (0 : ℂ) else (Real.sin v / v : ℂ)

theorem intervalIntegral_sin_div_kernel_symmetric_eq_two_mul_zero_to (A : ℝ) :
    (∫ v in (-A)..A,
      if v = 0 then (0 : ℂ) else (Real.sin v / v : ℂ)) =
      2 * ∫ v in 0..A,
        if v = 0 then (0 : ℂ) else (Real.sin v / v : ℂ)

private lemma log_ineq_3 (u : ℝ) (hu : 0 < u) :
    12 * u + 18 * u ^ 2 + 4 * u ^ 3 - u ^ 4 <
    12 * (1 + u) ^ 2 * Real.log (1 + u)

private lemma hasDerivAt_one_add_sq_mul_log (x : ℝ) (h1p : (0 : ℝ) < 1 + x) :
    HasDerivAt (fun u => (1 + u) ^ 2 * Real.log (1 + u))
      (2 * (1 + x) * Real.log (1 + x) + (1 + x)) x

private lemma hasDerivAt_one_add_pow_three_mul_log (x : ℝ) (h1p : (0 : ℝ) < 1 + x) :
    HasDerivAt (fun u => (1 + u) ^ 3 * Real.log (1 + u))
      (3 * (1 + x) ^ 2 * Real.log (1 + x) + (1 + x) ^ 2) x

private lemma hasDerivAt_one_add_pow_four_mul_log (x : ℝ) (h1p : (0 : ℝ) < 1 + x) :
    HasDerivAt (fun u => (1 + u) ^ 4 * Real.log (1 + u))
      (4 * (1 + x) ^ 3 * Real.log (1 + x) + (1 + x) ^ 3) x

private lemma log_ineq_5 (u : ℝ) (hu : 0 < u) :
    0 < 1680 * u ^ 4 + 3360 * u ^ 3 - 1440 * u ^ 2 + 2880 * u
      - 2880 * Real.log (1 + u)

lemma analyticOrderNatAt_fun_div_const {c z : ℂ} {f : ℂ → ℂ}
  (hc : c ≠ 0) (hfAnalytic : AnalyticAt ℂ f z) :
    analyticOrderNatAt (fun z => f z / c) z = analyticOrderNatAt f z

lemma HasDerivAt.of_hasDerivAt_ofReal_comp {z : ℝ} {f : ℝ → ℝ} {u : ℂ}
    (hf : HasDerivAt (fun y ↦ (f y : ℂ)) u z) :
    ∃ u' : ℝ, u = u' ∧ HasDerivAt f u' z

lemma BddAbove_to_IsBigO {f : ℂ → ℂ} {p : ℂ}
    {U : Set ℂ} (hU : U ∈ 𝓝 p) (bdd : BddAbove (norm ∘ f '' (U \ {p}))) :
    f =O[𝓝[≠] p] (1 : ℂ → ℂ)

theorem ZetaLowerBound3_aux2 {C : ℝ}
  {σ t : ℝ}
  (ζ_2t_bound : ‖ζ (σ + (2 * t) * I)‖ ≤ C * Real.log |2 * t|) :
  ‖ζ (σ + 2 * t * I)‖ ^ ((1 : ℝ) / 4) ≤ (C * Real.log |2 * t|) ^ ((1 : ℝ) / 4)

lemma bddAbove_square_of_tendsto {f : ℂ → β} {x : ℂ}
    (hf : Tendsto f (𝓝[≠] x) (𝓝 y)) :
    ∀ᶠ (c : ℝ) in 𝓝[>] 0, BddAbove (f '' (Square x c \ {x}))

