      · norm_num

:= by
      have h_fejer_uniform : ∀ ε > 0, ∃ N : ℕ, ∀ n ≥ N, ∀ x ∈ Set.Icc a b, |fejer_sum f n x - f x| < ε := by
        intro ε hε_pos
        obtain ⟨δ₀, hδ₀_pos, hδ₀⟩ : ∃ δ₀ > 0, ∀ x ∈ Set.Icc a b, ∀ t, |t| < δ₀ → |f (x - t) - f x| < ε / 2 := by
          have := @uniform_continuity_shift;
