                rw [ intervalIntegrable_iff_integrableOn_Ioc_of_le hab ] at *;
                have h_integrable : ∀ a b, a ≤ b → MeasureTheory.IntegrableOn f (Set.Ioc a b) MeasureTheory.volume := by
